"""Audit services/ against SPEC.md (rev 7) + SPEC-AMENDMENT-1.md (C16)."""
import ast
import json
import re
import sys
from pathlib import Path

ROOT = Path(sys.argv[1] if len(sys.argv) > 1 else ".").resolve()
SERVICES = ROOT / "services"
LFS_FIRST = "version https://git-lfs.github.com/spec/v1"
CLAUSES = ["C%d" % i for i in range(1, 17)]


def read(path):
    return path.read_text(encoding="utf-8", errors="replace")


def is_lfs_pointer(path):
    try:
        with path.open("rb") as fh:
            first = fh.readline().decode("utf-8", "replace")
    except OSError:
        return False
    return first.rstrip("\r\n") == LFS_FIRST


def py_files(src):
    return sorted(p for p in src.rglob("*.py") if p.is_file())


def parse(path):
    try:
        return ast.parse(read(path))
    except SyntaxError as exc:
        print("PARSE ERROR %s: %s" % (path, exc))
        return None


def check_c2(svc, ev):
    path = svc / "src" / "handlers.py"
    if not path.is_file():
        ev("C2", "handlers.py missing")
        return False
    tree = parse(path)
    if tree is None:
        ev("C2", "handlers.py unparseable")
        return False
    ok = True
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name.startswith("handle_"):
            if ast.get_docstring(node) is None:
                ok = False
                ev("C2", "%s at line %d has no docstring" % (node.name, node.lineno))
    return ok


def check_c3(svc, ev):
    ok = True
    for path in py_files(svc / "src"):
        tree = parse(path)
        if tree is None:
            continue
        for node in ast.walk(tree):
            if isinstance(node, ast.Call):
                f = node.func
                if isinstance(f, ast.Name) and f.id == "print":
                    ok = False
                    ev("C3", "%s:%d print() call" % (path.relative_to(svc), node.lineno))
                elif isinstance(f, ast.Attribute) and f.attr == "print" and isinstance(f.value, ast.Name) and f.value.id == "builtins":
                    ok = False
                    ev("C3", "%s:%d builtins.print() call" % (path.relative_to(svc), node.lineno))
    return ok


def check_c5(svc, ev):
    path = svc / "Dockerfile"
    if not path.is_file():
        ev("C5", "Dockerfile missing")
        return False
    ok = True
    seen = False
    for i, line in enumerate(read(path).splitlines(), 1):
        parts = line.strip().split()
        if parts and parts[0].upper() == "FROM":
            seen = True
            ref = parts[1] if len(parts) > 1 else ""
            if not re.search(r"@sha256:[0-9a-f]{64}$", ref):
                ok = False
                ev("C5", "line %d: %r" % (i, ref))
    if not seen:
        ev("C5", "no FROM line")
        return False
    return ok


def check_c6(svc, ev):
    path = svc / "Dockerfile"
    if not path.is_file():
        return False
    users = []
    for i, line in enumerate(read(path).splitlines(), 1):
        parts = line.strip().split()
        if parts and parts[0].upper() == "USER":
            users.append((i, parts[1] if len(parts) > 1 else ""))
    if not users:
        ev("C6", "no USER line")
        return False
    lineno, name = users[-1]
    if name.lower() in ("root", "0"):
        ev("C6", "last USER line %d names %r" % (lineno, name))
        return False
    return True


def check_c7(svc, ev):
    path = svc / "README.md"
    if not path.is_file():
        ev("C7", "README.md missing")
        return False
    lines = read(path).splitlines()
    if "## Runbook" not in lines:
        ev("C7", "no exact '## Runbook' line; headings: %r" % [l for l in lines if l.startswith("#")])
        return False
    return True


def check_c8(svc, cfg, ev):
    path = svc / "CODEOWNERS"
    if not path.is_file():
        ev("C8", "CODEOWNERS missing")
        return False
    want = "@team-%s" % cfg.get("team")
    rules = []
    for i, line in enumerate(read(path).splitlines(), 1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        parts = stripped.split()
        if parts[0] == "*":
            rules.append((i, parts[1:]))
    if not rules:
        ev("C8", "no '*' rule")
        return False
    for lineno, owners in rules:
        if want in owners:
            return True
    ev("C8", "'*' rule owners %r != %r" % ([o for _, o in rules], want))
    return False


def check_c9(svc, ev):
    ok = True
    for path in py_files(svc / "src"):
        tree = parse(path)
        if tree is None:
            continue
        for node in ast.walk(tree):
            values = []
            if isinstance(node, ast.Constant) and isinstance(node.value, str):
                values.append(node.value)
            elif isinstance(node, ast.JoinedStr):
                values.extend(
                    v.value for v in node.values
                    if isinstance(v, ast.Constant) and isinstance(v.value, str)
                )
            for val in values:
                if val.startswith("sk_live_") or val.startswith("AKIA"):
                    ok = False
                    ev("C9", "%s:%d %r" % (path.relative_to(svc), getattr(node, "lineno", 0), val[:40]))
    return ok


def check_c10(svc, cfg, ev):
    hc = cfg.get("healthcheck")
    if not hc:
        ev("C10", "no healthcheck in config.json")
        return False
    seg = str(hc).rstrip("/").split("/")[-1]
    want = "handle_" + seg
    path = svc / "src" / "handlers.py"
    if not path.is_file():
        ev("C10", "handlers.py missing")
        return False
    tree = parse(path)
    if tree is None:
        ev("C10", "handlers.py unparseable")
        return False
    names = {n.name for n in ast.walk(tree) if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))}
    if want not in names:
        ev("C10", "healthcheck %r needs %s; defined: %r" % (hc, want, sorted(n for n in names if n.startswith("handle_"))))
        return False
    return True


def check_c12(svc, ev):
    path = svc / "requirements.txt"
    if not path.is_file():
        ev("C12", "requirements.txt missing")
        return False
    ok = True
    pin = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]*==[A-Za-z0-9][A-Za-z0-9._+!-]*$")
    for i, line in enumerate(read(path).splitlines(), 1):
        s = line.strip()
        if not s or s.startswith("#"):
            continue
        if not pin.match(s):
            ok = False
            ev("C12", "line %d: %r" % (i, s))
    return ok


def int_val(v):
    return isinstance(v, int) and not isinstance(v, bool)


def numbers_ok(svc, cfg):
    bad = []

    def mark(clause, msg):
        bad.append((clause, msg))

    public = cfg.get("exposure") == "public"
    if public:
        t = cfg.get("timeout_s")
        if not (int_val(t) or isinstance(t, float)) or t > 30:
            mark("C1", "timeout_s=%r" % (t,))
    r = cfg.get("retries")
    if not int_val(r) or not (1 <= r <= 5):
        mark("C4", "retries=%r" % (r,))
    if cfg.get("metrics_port") == cfg.get("port"):
        mark("C11", "metrics_port=%r port=%r" % (cfg.get("metrics_port"), cfg.get("port")))
    if str(cfg.get("log_level", "")).upper() == "DEBUG":
        mark("C13", "log_level=%r" % (cfg.get("log_level"),))
    if public:
        m = cfg.get("max_body_kb")
        if not int_val(m) or m > 1024:
            mark("C14", "max_body_kb=%r" % (m,))
        rl = cfg.get("rate_limit_rps")
        if not int_val(rl) or not (1 <= rl <= 10000):
            mark("C16", "rate_limit_rps=%r" % (rl,))
    return bad


def check_c15(svc, ev):
    tests = svc / "tests"
    if not tests.is_dir():
        ev("C15", "no tests/ dir")
        return False
    names = [p.name for p in tests.rglob("test_*.py") if p.is_file()]
    if not names:
        ev("C15", "no test_*.py; contents: %r" % sorted(p.name for p in tests.iterdir()))
        return False
    return True


def audit(svc):
    evidence = []

    def ev(clause, msg):
        evidence.append((clause, msg))

    cfg = {}
    cfg_path = svc / "config.json"
    if cfg_path.is_file():
        try:
            cfg = json.loads(read(cfg_path))
        except json.JSONDecodeError as exc:
            ev("config", "config.json invalid: %s" % exc)
    else:
        ev("config", "config.json missing")

    pointers = sorted(
        str(p.relative_to(svc)) for p in svc.rglob("*") if p.is_file() and is_lfs_pointer(p)
    )
    if pointers:
        return "unverifiable", [], evidence + [("LFS", "pointers: %s" % ", ".join(pointers))]

    failed = set()
    for clause, msg in numbers_ok(svc, cfg):
        failed.add(clause)
        ev(clause, msg)
    checks = [
        ("C2", check_c2(svc, ev)),
        ("C3", check_c3(svc, ev)),
        ("C5", check_c5(svc, ev)),
        ("C6", check_c6(svc, ev)),
        ("C7", check_c7(svc, ev)),
        ("C8", check_c8(svc, cfg, ev)),
        ("C9", check_c9(svc, ev)),
        ("C10", check_c10(svc, cfg, ev)),
        ("C12", check_c12(svc, ev)),
        ("C15", check_c15(svc, ev)),
    ]
    for clause, ok in checks:
        if not ok:
            failed.add(clause)
    violations = [c for c in CLAUSES if c in failed]
    return ("violations" if violations else "compliant"), violations, evidence


def main():
    results = {}
    for svc in sorted(p for p in SERVICES.iterdir() if p.is_dir()):
        status, violations, evidence = audit(svc)
        results[svc.name] = (status, violations)
        print("=== %s: %s %s" % (svc.name, status, violations))
        for clause, msg in evidence:
            print("    [%s] %s" % (clause, msg))
    print("\nSUMMARY")
    for name, (status, violations) in sorted(results.items()):
        print("%s %s %s" % (name, status, " ".join(violations)))


if __name__ == "__main__":
    main()

